<template>
  <div class="table-structure-demo">
    <div class="table-demo-tabs" role="tablist" aria-label="Table structure" @keydown="onTabKey">
      <button v-for="(tab, index) in tabs" :key="tab" :id="`${uid}-tab-${index}`" role="tab" type="button" :aria-selected="active === index" :tabindex="active === index ? 0 : -1" :aria-controls="`${uid}-panel`" @click="active = index">{{ tab }}</button>
    </div>
    <div :id="`${uid}-panel`" role="tabpanel" :aria-labelledby="`${uid}-tab-${active}`" class="table-demo-sheet">
      <p class="table-demo-document">Studio booking guide <span>Illustrative example</span></p>
      <table v-if="active === 0" class="specimen-table">
        <caption class="sr-only">A shared studio booking rule expressed through merged cells</caption>
        <thead><tr><th rowspan="2" scope="col">Space</th><th colspan="2" scope="colgroup" class="structure-cell">Booking limits</th></tr><tr><th scope="col">Session</th><th scope="col">Capacity</th></tr></thead>
        <tbody><tr><th rowspan="2" scope="rowgroup" class="structure-cell">Studio</th><td>Morning</td><td>8 people</td></tr><tr><td>Evening</td><td>6 people</td></tr><tr><th scope="row">Workshop</th><td>All day</td><td>12 people</td></tr></tbody>
      </table>
      <table v-else class="specimen-table">
        <caption class="sr-only">A booking table containing a smaller table of access rules inside one cell</caption>
        <thead><tr><th scope="col">Space</th><th scope="col">Access</th></tr></thead>
        <tbody><tr><th scope="row">Studio</th><td class="nested-cell structure-cell"><table class="inner-table"><caption>By session</caption><thead><tr><th scope="col">Session</th><th scope="col">Access</th></tr></thead><tbody><tr><td>Morning</td><td>Open booking</td></tr><tr><td>Evening</td><td>Members only</td></tr></tbody></table></td></tr><tr><th scope="row">Workshop</th><td>Open booking</td></tr></tbody>
      </table>
    </div>
    <p class="table-demo-note">{{ active === 0 ? 'The shared heading applies to both columns. The studio label applies to both sessions.' : 'The evening restriction belongs to the studio’s inner table. Its parent cell supplies the context.' }}</p>
    <button class="table-code-toggle" type="button" :aria-expanded="showCode" :aria-controls="`${uid}-code`" @click="showCode = !showCode">{{ showCode ? 'Hide HTML' : 'Inspect HTML' }}<span aria-hidden="true">{{ showCode ? '−' : '+' }}</span></button>
    <pre v-if="showCode" :id="`${uid}-code`" class="table-code"><code>{{ active === 0 ? mergedHTML : nestedHTML }}</code></pre>
  </div>
</template>
<script>
let serial = 0;
export default {
  name: 'TableStructureDemo',
  data() { return {
    uid: `table-structure-${++serial}`, active: 0, showCode: false, tabs: ['Merged cells', 'Nested table'],
    mergedHTML: '<th colspan="2">Booking limits</th>\n\n<tr>\n  <th rowspan="2">Studio</th>\n  <td>Morning</td><td>8 people</td>\n</tr>\n<tr>\n  <td>Evening</td><td>6 people</td>\n</tr>',
    nestedHTML: '<tr>\n  <th>Studio</th>\n  <td>\n    <table>\n      <caption>By session</caption>\n      <tr><td>Morning</td><td>Open booking</td></tr>\n      <tr><td>Evening</td><td>Members only</td></tr>\n    </table>\n  </td>\n</tr>',
  }; },
  methods: { onTabKey(event) {
    if (!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) return;
    event.preventDefault(); event.stopPropagation();
    this.active = event.key === 'Home' ? 0 : event.key === 'End' ? 1 : 1 - this.active;
    this.$nextTick(() => this.$el.querySelector('[aria-selected="true"]').focus());
  } },
};
</script>
<style scoped>
