.table-structure-demo { --table-rule: rgb(128 128 128 / 28%); --table-highlight: rgb(128 128 128 / 12%); color: var(--case-ink); font-family: 'Quattrocento Sans', sans-serif; }
.table-demo-tabs { display: flex; gap: 1.6rem; border-bottom: 1px solid var(--case-rule); margin-bottom: 1.4rem; }
.table-demo-tabs button { padding: .6rem 0; min-height: 44px; border: 0; border-bottom: 1px solid transparent; background: none; color: var(--case-muted); font: 600 14px/1.5 'Quattrocento Sans', sans-serif; cursor: var(--site-interactive-cursor); }
.table-demo-tabs button[aria-selected="true"] { color: var(--case-ink); border-bottom-color: currentColor; }
.table-demo-sheet { padding: 1.4rem; background: rgb(128 128 128 / 5%); }
.table-demo-document { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .4rem; margin: 0 0 1.3rem; font-size: 14px; font-weight: 600; }
.table-demo-document span { font-size: 11px; color: var(--case-muted); font-weight: 400; }
.specimen-table { border-collapse: collapse; width: 100%; font-size: 14px; line-height: 1.5; }
.specimen-table th, .specimen-table td { padding: .8rem .65rem; border: 1px solid var(--table-rule); text-align: left; }
.specimen-table th { font-weight: 600; }
.specimen-table .structure-cell { background: var(--table-highlight); }
.specimen-table .nested-cell { padding: .6rem; }
.inner-table { border-collapse: collapse; width: 100%; font-size: 13px; }
.inner-table caption { text-align: left; font-size: 11px; color: var(--case-muted); padding: .1rem 0 .5rem; }
.inner-table th, .inner-table td { padding: .5rem; }
.table-demo-note { font-size: 14px; line-height: 1.65; color: var(--case-muted); margin: 1rem 0 .2rem; }
.table-code-toggle { display: inline-flex; gap: 1rem; align-items: center; min-height: 44px; padding: 0; border: 0; background: none; font: 13px/1.5 'Quattrocento Sans', sans-serif; color: var(--case-muted); cursor: var(--site-interactive-cursor); }
.table-code { padding: 1rem; margin: .3rem 0 0; overflow: auto; font-size: 12px; line-height: 1.7; background: var(--table-highlight); }
button:focus-visible { outline: 2px solid currentColor; outline-offset: 4px; }
@media (max-width: 600px) { .table-demo-sheet { padding: 1rem .6rem; } .specimen-table { font-size: 13px; } .specimen-table th, .specimen-table td { padding: .65rem .4rem; } .inner-table { font-size: 12px; } }
</style>
